-- 0001_init: core management MVP schema.
--
-- Identifiers are UUIDv4 values generated by the application. Text columns use
-- explicit CHECK constraints so validation also holds at the database layer.

CREATE TABLE users (
    id uuid PRIMARY KEY,
    username text NOT NULL UNIQUE,
    display_name text NOT NULL DEFAULT '',
    webauthn_user_handle bytea NOT NULL UNIQUE,
    status text NOT NULL DEFAULT 'pending',
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT users_username_format CHECK (username ~ '^[a-z0-9][a-z0-9._-]{2,63}$'),
    CONSTRAINT users_display_name_length CHECK (char_length(display_name) <= 200),
    CONSTRAINT users_user_handle_size CHECK (octet_length(webauthn_user_handle) BETWEEN 1 AND 64),
    CONSTRAINT users_status_values CHECK (status IN ('pending', 'active'))
);

CREATE TABLE passkeys (
    id uuid PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    credential_id bytea NOT NULL UNIQUE,
    public_key bytea NOT NULL,
    attestation_type text NOT NULL DEFAULT '',
    attestation_format text NOT NULL DEFAULT '',
    transports text[] NOT NULL DEFAULT '{}',
    sign_count bigint NOT NULL DEFAULT 0,
    backup_eligible boolean NOT NULL DEFAULT false,
    backup_state boolean NOT NULL DEFAULT false,
    user_verified boolean NOT NULL DEFAULT false,
    aaguid bytea,
    last_used_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT passkeys_sign_count_range CHECK (sign_count >= 0)
);

CREATE INDEX passkeys_user_idx ON passkeys(user_id);

CREATE TABLE sessions (
    id uuid PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token_hash bytea NOT NULL UNIQUE,
    csrf_hash bytea NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    last_seen_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL,
    revoked_at timestamptz
);

CREATE INDEX sessions_user_idx ON sessions(user_id);
CREATE INDEX sessions_expiry_idx ON sessions(expires_at);

CREATE TABLE enrollment_permits (
    id uuid PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    code_hash bytea NOT NULL UNIQUE,
    attempts integer NOT NULL DEFAULT 0,
    expires_at timestamptz NOT NULL,
    used_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT enrollment_permits_attempts_range CHECK (attempts >= 0)
);

CREATE TABLE auth_states (
    id uuid PRIMARY KEY,
    kind text NOT NULL,
    user_id uuid REFERENCES users(id) ON DELETE CASCADE,
    permit_id uuid REFERENCES enrollment_permits(id) ON DELETE SET NULL,
    data jsonb NOT NULL,
    expires_at timestamptz NOT NULL,
    consumed_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT auth_states_kind_values CHECK (kind IN ('register', 'login'))
);

CREATE INDEX auth_states_expiry_idx ON auth_states(expires_at);

CREATE TABLE sites (
    id uuid PRIMARY KEY,
    slug text NOT NULL UNIQUE,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT sites_slug_format CHECK (slug ~ '^[a-z0-9][a-z0-9-]{0,62}$')
);

CREATE TABLE site_settings (
    site_id uuid PRIMARY KEY REFERENCES sites(id) ON DELETE CASCADE,
    name text NOT NULL,
    description text NOT NULL DEFAULT '',
    default_locale text NOT NULL DEFAULT 'zh-CN',
    revision bigint NOT NULL DEFAULT 1,
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT site_settings_name_length CHECK (char_length(name) BETWEEN 1 AND 200),
    CONSTRAINT site_settings_description_length CHECK (char_length(description) <= 1000),
    CONSTRAINT site_settings_locale_values CHECK (default_locale IN ('zh-CN', 'en-US')),
    CONSTRAINT site_settings_revision_positive CHECK (revision > 0)
);

CREATE TABLE site_memberships (
    site_id uuid NOT NULL REFERENCES sites(id) ON DELETE CASCADE,
    user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    role text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (site_id, user_id),
    CONSTRAINT site_memberships_role_values CHECK (role IN ('owner', 'editor', 'viewer'))
);

CREATE INDEX site_memberships_user_idx ON site_memberships(user_id);
